import{z as s,x as n,o as B,c as C,q as t,j as o,D as a,d as A,s as l,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Rowhammer 缓解","description":"","frontmatter":{"title":"Rowhammer 缓解","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rowhammer-mitigations.md","filePath":"cs/rowhammer-mitigations.md","lastUpdated":1791063341000}'),m={name:"cs/rowhammer-mitigations.md"};function d(h,E,p,R,c,D){const r=n("Mermaid");return B(),C("div",null,[E[2]||(E[2]=t('<h1 id="rowhammer-缓解" tabindex="-1">Rowhammer 缓解 <a class="header-anchor" href="#rowhammer-缓解" aria-label="Permalink to &quot;Rowhammer 缓解&quot;">​</a></h1><div class="epigraph"><p>反复敲击 DRAM 行可使相邻行比特翻转。缓解是目标刷新、ECC、隔离敏感页、降低访问强度。它把内存从「可靠存储」改回物理设备。</p><footer>—— Kim et al., Flipping Bits in Memory Without Accessing Them, ISCA 2014</footer></div><p>上一课<a href="/cs/spectre-mitigations">Spectre</a>处理 CPU 前端的预测执行；缺口下沉一层，来到 <strong>DRAM 本身的物理扰动</strong>。本课讲翻转机理与缓解分层，不给打穿的具体操作步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>隔离模型默认内存比特在不被写时保持稳定——你没写别人的页，就读不出变化。Rowhammer 打破的正是这条假设：对同一 DRAM 行高频反复激活，相邻行的电容被感应泄漏，从未被触摸的页里也会翻转比特。缺口是缓解怎么分层：目标行刷新（TRR）、ECC、减少 clflush 一类绕过缓存的高频访问、以及云上禁止与敏感数据共驻。</p><p><span class="marginnote">直觉类比：Rowhammer 像有人隔着图书馆的墙反复蹦跳，墙那边书架上的书——你没碰过的页——被震得掉下来几本。书没人动过，位置却变了，「不写即不变」的合同就此作废。</span></p><h3 id="ecc-不是万能" tabindex="-1">ECC 不是万能 <a class="header-anchor" href="#ecc-不是万能" aria-label="Permalink to &quot;ECC 不是万能&quot;">​</a></h3><p>服务器级 ECC 对每个 64 比特字通常只配 8 个校验位，能纠正单比特、检测双比特；Rowhammer 一次能在同一字里翻出更多比特，纠错子直接失守，若翻的恰是校验位本身，错误还会被当成「已纠正」静默放行。</p><p><span class="marginnote">数字实例：SECDED 编码对 64 比特数据只有 8 个校验位，能力边界是「纠 1 检 2」；同一个字里一次翻 3 比特，校验码就算不出唯一的原值——错值被当作真值交给 CPU，程序毫无察觉。</span></p><p><span class="marginnote">Kim et al. 2014。禁止 Rowhammer 利用教程。Flush+Reload 下一课是缓存侧信道经典。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法不是堵某个漏洞，而是先陈述扰动物理再分层配对策：硬件层靠 TRR 在激活邻行时插入刷新，靠 ECC 兜住残余翻转；软件层靠去掉 clflush 一类精确驱逐原语，抬高攻击者维持高频访问的成本；部署层靠页隔离与共驻审计，把攻击者的物理行与敏感行分开。每一层都只是抬高代价，不是根除。下一课 Flush+Reload。</p>',13)),(B(),o(i,null,{default:a(()=>[l(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20HAMMER%5B%22%E9%AB%98%E9%A2%91%E8%A1%8C%E8%AE%BF%E9%97%AE%22%5D%20--%3E%20FLIP%5B%22%E9%82%BB%E8%A1%8C%E7%BF%BB%E8%BD%AC%22%5D%0A%20%20FLIP%20--%3E%20MIT%5B%22TRR%20ECC%20%E9%9A%94%E7%A6%BB%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"Rowhammer 把硬件可靠性重新放进安全模型：此前 DRAM 的比特翻转被当成宇宙射线级的概率噪声，交给 ECC 静默吸收；现在翻转可由用户态程序定向制造，内存从「可靠存储」退回物理设备。评价缓解要看它封的是哪条失效路径：TRR 假设攻击者只能锤有限几行，双面锤击恰好顶到这条假设；ECC 假设错误稀疏且独立，定向多比特翻转违背独立性。缓存侧信道下一课不翻转比特，只测时间。",-1)),E[5]||(E[5]=e("p",null,"各层缓解各自封住哪条失效路径，又各自被什么顶穿：",-1)),(B(),o(i,null,{default:a(()=>[l(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%94%BB%E5%87%BB%E8%80%85%E9%AB%98%E9%A2%91%E6%BF%80%E6%B4%BB%E5%90%8C%E4%B8%80%E7%89%A9%E7%90%86%E8%A1%8C%22%5D%20--%3E%20B%7B%22%E7%BC%93%E8%A7%A3%E5%9C%A8%E5%93%AA%E4%B8%80%E5%B1%82%E6%8B%A6%E6%88%AA%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%22%E7%A1%AC%E4%BB%B6%22%7C%20TRR%5B%22TRR%EF%BC%9A%E6%BF%80%E6%B4%BB%E6%97%B6%E6%8D%8E%E5%B8%A6%E5%88%B7%E6%96%B0%E9%82%BB%E8%A1%8C%22%5D%0A%20%20B%20--%3E%7C%22%E7%A1%AC%E4%BB%B6%22%7C%20ECC%5B%22ECC%EF%BC%9A%E7%BA%A0%E5%8D%95%E6%AF%94%E7%89%B9%E3%80%81%E6%A3%80%E5%8F%8C%E6%AF%94%E7%89%B9%22%5D%0A%20%20B%20--%3E%7C%22%E8%BD%AF%E4%BB%B6%22%7C%20SW%5B%22%E5%8E%BB%E6%8E%89%20clflush%20%E7%B2%BE%E7%A1%AE%E9%A9%B1%E9%80%90%E5%8E%9F%E8%AF%AD%22%5D%0A%20%20B%20--%3E%7C%22%E9%83%A8%E7%BD%B2%22%7C%20ISO%5B%22%E9%A1%B5%E9%9A%94%E7%A6%BB%E4%B8%8E%E5%85%B1%E9%A9%BB%E5%AE%A1%E8%AE%A1%22%5D%0A%20%20TRR%20--%3E%20T2%7B%22%E5%8F%8C%E9%9D%A2%E9%94%A4%E5%87%BB%E9%A1%B6%E7%A9%BF%20TRR%20%E5%81%87%E8%AE%BE%EF%BC%9F%22%7D%0A%20%20ECC%20--%3E%20E2%7B%22%E5%AE%9A%E5%90%91%E5%A4%9A%E6%AF%94%E7%89%B9%E7%BF%BB%E8%BD%AC%E8%BF%9D%E8%83%8C%E7%8B%AC%E7%AB%8B%E6%80%A7%EF%BC%9F%22%7D%0A%20%20T2%20--%3E%7C%22%E5%8F%AF%E8%83%BD%22%7C%20R%5B%22%E6%AE%8B%E4%BD%99%E9%A3%8E%E9%99%A9%EF%BC%9A%E5%8F%AA%E6%98%AF%E6%8A%AC%E9%AB%98%E4%BB%A3%E4%BB%B7%22%5D%0A%20%20E2%20--%3E%7C%22%E6%98%AF%22%7C%20R%0A%20%20SW%20--%3E%20R%0A%20%20ISO%20--%3E%20R%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p><span class="marginnote">为什么重要：把 ECC 当成「内存已诚实」的证明，云上就会放松共驻审计；等新一代颗粒的 TRR 被绕过时，敏感页早已与攻击者行贴在一起。缓解是追赶关系，分层抬价才是常态——没有一劳永逸的根除。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课零利用：不给凑行地址，不给锤击序列。ECC 只能纠正有限翻转，不能当「内存已诚实」的证明；TRR 也在更新的颗粒上屡被绕过——两者是追赶关系。Flush+Reload 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Spectre 测微结构；Rowhammer 翻 DRAM 比特。</li><li>刷新、ECC、隔离页提高代价。</li><li>内存不是抽象可靠寄存器。</li><li>下一课 Flush+Reload。</li><li>出处：Kim et al., ISCA 2014。</li></ul>',5))])}const T=s(m,[["render",d]]);export{u as __pageData,T as default};
